old = json.loads(OUT.read_text()) if OUT.exists() else {}
images = {s['slug']:s.get('image',{}) for s in old.get('stops',[])}
stops=[]
for i,(slug,title,subtitle,lat,lng,what,history,look,keys,directions,minutes) in enumerate(RAW,1):
    sections={'what':what,'history':history,'look':look}
    narration=f'{i}. {title}. Что это. {what} История. {history} На что смотреть. {look}'
    stops.append(dict(id=i,slug=slug,title=title,subtitle=subtitle,lat=lat,lng=lng,sections=sections,narration=narration,
        image=images.get(slug,dict(src=f'/images/{i:02d}-{slug}.jpg',alt=title,author='Атрибуция готовится',license='Проверяется',sourceUrl='https://commons.wikimedia.org/')),
        sources=[dict(label=S[k][0],url=S[k][1]) for k in keys],nextDirections=directions,walkMinutes=minutes))

def practical(title,text,key=None,verified=True):
    d=dict(title=title,text=text,verified=verified)
    if key:d['url']=S[key][1]
    return d

